-- Katalog seed — catalog_data JSON'larından scripts/seed-catalog.ts ile üretildi.
-- Yeniden üretmek için: npx tsx scripts/seed-catalog.ts --kinds motor --brands SEW-EURODRIVE --replace --out 20260829000004_sew_motor_reseed
-- Toplam 49 ürün.

do $sew_motor_seed$
begin

-- Bu markanın katalog satırları kaynak JSON'dan yeniden üretilir.
delete from public.cat_equipment where brand in ('SEW-EURODRIVE') and kind in ('motor');


on conflict (key) do update set value = excluded.value, updated_at = now();

end
$sew_motor_seed$;
